// Transliteration (src/script.mjs) against VRI's own script editions.
// Fixture: tests/fixtures/scripts/vri-pairs.json.gz, regenerated by
// scripts/canon/sample_scripts.py from tipitaka-xml at the pinned commit.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import zlib from 'node:zlib';
import {
  SCRIPTS, transliterate, toRoman, detectScript, scriptName,
  romanizeInput, localizeText, localizeSearch, localizeDescribe,
} from '../src/script.mjs';
import * as canon from '../src/canon.mjs';

const FIXTURE = new URL('./fixtures/scripts/vri-pairs.json.gz', import.meta.url);
const fixture = JSON.parse(zlib.gunzipSync(fs.readFileSync(FIXTURE)).toString('utf8'));
const NAMES = { deva: 'devanagari', sinh: 'sinhala', thai: 'thai', mymr: 'myanmar', khmr: 'khmer' };
const TARGET = 0.995;

// The editions frame the "Namo tassa…" invocation with a danda on both sides; the Roman edition does not.
const unframe = (edition, roman) => (/^Namo tassa/.test(roman) ? edition.replace(/^[॥ฯ။។] (.*?) ?[॥ฯ။។]$/u, '$1') : edition);

// Punctuation an edition writes the same way for two Roman marks cannot be told apart on the way back:
// Devanagari and Myanmar end every verse line with a danda (Roman ";" or "."), and Myanmar writes "…" as ။.
function fold(roman, code) {
  let x = roman.toLowerCase();
  if (code === 'deva' || code === 'mymr') x = x.replace(/;(\)?\s*)$/, '.$1');
  if (code === 'mymr') x = x.replace(/…(\s*)pe…/g, '\u0001$1pe\u0002').replace(/…/g, '.').replace(/[\u0001\u0002]/g, '…');
  return x;
}

function rates(items, code) {
  const script = NAMES[code];
  let to = 0;
  let back = 0;
  const misses = [];
  for (const item of items) {
    const edition = unframe(item[code], item.romn);
    const stanza = (item.rend ?? '').startsWith('gatha');
    const got = transliterate(item.romn, 'roman', script, { stanza });
    if (got === edition) to += 1; else misses.push({ dir: 'to', file: item.file, p: item.p ?? item.note, got, want: edition });
    const roman = transliterate(edition, script, 'roman');
    if (roman === fold(item.romn, code)) back += 1; else misses.push({ dir: 'back', file: item.file, p: item.p ?? item.note, got: roman, want: fold(item.romn, code) });
  }
  return { to: to / items.length, back: back / items.length, misses };
}

test('fixture is pinned, compact and large enough', () => {
  assert.equal(fixture.source.commit, '2d134ff9ef60f70a1eb03c9370580228811a3070');
  assert.match(fixture.source.repository, /VipassanaTech\/tipitaka-xml$/);
  assert.deepEqual(fixture.scripts, ['deva', 'sinh', 'thai', 'mymr', 'khmr']);
  assert.deepEqual(fixture.source.absent_scripts, ['laoo', 'lana']);
  for (const [file, sha] of Object.entries(fixture.source.files_sha256)) assert.match(sha, /^[0-9a-f]{64}$/, file);
  assert.ok(fixture.paragraphs.length >= 500, `${fixture.paragraphs.length} paragraphs`);
  assert.ok(fs.statSync(FIXTURE).size <= 3 * 1024 * 1024, 'fixture must stay under 3 MB');
});

for (const code of ['deva', 'sinh', 'thai', 'mymr', 'khmr']) {
  test(`${NAMES[code]}: matches the VRI ${code} edition both ways (≥ 99.5% exact)`, () => {
    const { to, back, misses } = rates(fixture.paragraphs, code);
    const detail = JSON.stringify(misses.slice(0, 3), null, 1);
    assert.ok(to >= TARGET, `Roman → ${code}: ${(to * 100).toFixed(2)}%\n${detail}`);
    assert.ok(back >= TARGET, `${code} → Roman: ${(back * 100).toFixed(2)}%\n${detail}`);
  });
  test(`${NAMES[code]}: variant-reading notes (abbreviations) mostly match`, () => {
    const { to, back } = rates(fixture.notes, code);
    assert.ok(to >= 0.97 && back >= 0.97, `notes ${code}: to ${to}, back ${back}`);
  });
}

test('every script round-trips the sampled Roman text', () => {
  for (const script of SCRIPTS.filter((s) => s !== 'roman')) {
    let ok = 0;
    for (const { romn } of fixture.paragraphs) {
      const back = transliterate(transliterate(romn, 'roman', script), script, 'roman');
      const code = { devanagari: 'deva', myanmar: 'mymr' }[script];
      if (back === fold(romn, code)) ok += 1;
    }
    // Lao and Lanna have no VRI edition at the pinned commit: their letters must round-trip exactly.
    const need = script === 'lao' || script === 'lanna' ? 1 : TARGET;
    assert.ok(ok / fixture.paragraphs.length >= need, `${script}: ${ok}/${fixture.paragraphs.length}`);
  }
});

test('known words in every script', () => {
  const buddha = {
    devanagari: 'बुद्ध', sinhala: 'බුද්\u200cධ', thai: 'พุทฺธ', myanmar: 'ဗုဒ္ဓ', khmer: 'ពុទ្ធ', lao: 'ພຸທ຺ຘ', lanna: 'ᨻᩩᨴ᩠ᨵ',
  };
  for (const [script, word] of Object.entries(buddha)) {
    assert.equal(transliterate('Buddha', 'roman', script), word, script);
    assert.equal(transliterate(word, script, 'roman'), 'buddha', script);
    assert.equal(detectScript(word), script);
  }
  assert.equal(transliterate('Saṅgha', 'roman', 'myanmar'), 'သင်္ဃ');
  assert.equal(transliterate('tassa dhammo', 'roman', 'myanmar'), 'တဿ ဓမ္မော');
  assert.equal(transliterate('paññā', 'roman', 'myanmar'), 'ပညာ');
  assert.equal(transliterate('evaṃ me sutaṃ', 'roman', 'thai'), 'เอวํ เม สุตํ');
  assert.equal(transliterate('Ekaṃ samayaṃ bhagavā', 'roman', 'devanagari'), 'एकं समयं भगवा');
  assert.equal(transliterate('kho', 'roman', 'lao'), 'ໂຂ');
  assert.equal(transliterate('ᨻᩩᨴ᩠ᨵᩮᩣ', 'lanna', 'roman'), 'buddho');
  // Mixed input: only the script part changes.
  assert.equal(toRoman('MN 10 मज्झिम'), 'MN 10 majjhima');
  assert.equal(toRoman('Satipaṭṭhāna'), 'Satipaṭṭhāna');
});

test('script names and codes', () => {
  assert.equal(scriptName('Burmese'), 'myanmar');
  assert.equal(scriptName('mymr'), 'myanmar');
  assert.equal(scriptName('Tai Tham'), 'lanna');
  assert.equal(scriptName('deva'), 'devanagari');
  assert.throws(() => scriptName('klingon'), /Available: roman, sinhala/);
  assert.equal(transliterate('बुद्ध', 'auto', 'thai'), 'พุทฺธ');
});

test('input in any script resolves and searches like Roman', () => {
  for (const ref of ['मज्झिमनिकाय १०', 'มชฺฌิมนิกาย ๑๐', 'မဇ္ဈိမနိကာယ ၁၀', 'මජ්ඣිමනිකාය 10', 'មជ្ឈិមនិកាយ ១០']) {
    const input = romanizeInput(ref);
    assert.equal(input.text, 'majjhimanikāya 10', ref);
    assert.equal(canon.resolve(input.text).unit.id, 'mn10', ref);
  }
  assert.deepEqual(romanizeInput('MN 10'), { text: 'MN 10', script: 'roman' });
  const roman = canon.search('satipaṭṭhāna', { limit: 3 });
  const thai = canon.search(romanizeInput('สติปฏฺฐาน').text, { limit: 3 });
  assert.deepEqual(thai.results.map((r) => r.id), roman.results.map((r) => r.id));
});

test('results in a script keep IDs, citations and English in Roman', () => {
  const { unit, notes } = canon.resolve('Dhp 1');
  const segments = canon.segments(unit, { includeNotes: true });
  const text = localizeText({ text_id: unit.id, citation: unit.acronym, title: unit.title, segments }, 'devanagari');
  assert.equal(text.text_id, 'dhp1');
  assert.equal(text.citation, 'Dhp 1');
  assert.equal(text.title_roman, 'Yamakavaggo');
  assert.equal(text.title, 'यमकवग्गो');
  assert.equal(text.script, 'devanagari');
  assert.match(text.script_note, /transliterated/);
  const stanza = text.segments.find((s) => s.type === 'verse');
  assert.equal(stanza.text.split('\n').length, 3);
  assert.ok(stanza.text.startsWith('मनोपुब्बङ्गमा धम्मा, मनोसेट्ठा मनोमया।'), stanza.text);
  assert.ok(stanza.text.endsWith('॥'), stanza.text);
  assert.equal(stanza.vri_paragraph, '1');

  const described = localizeDescribe(canon.describe(unit, notes), 'thai', romanizeInput('ธมฺมปท ๑'));
  assert.equal(described.id, 'dhp1');
  assert.equal(described.title, 'ยมกวคฺโค');
  assert.equal(described.input_romanized, 'dhammapada 1');
  assert.ok(described.english.every((e) => /^[\x20-\x7e]+$/.test(e.translator.normalize('NFD').replace(/[̀-ͯ]/g, ''))));

  const found = localizeSearch(canon.search('satipaṭṭhāna', { limit: 2 }), 'myanmar');
  assert.ok(found.results.every((r) => r.title_roman && /[က-႟]/.test(r.title)));
  assert.ok(found.results.every((r) => /^[a-z0-9.-]+$/.test(r.id)));

  // Roman (or no script) leaves results untouched.
  const plain = canon.describe(unit, notes);
  assert.deepEqual(localizeDescribe(plain, undefined), plain);
  assert.deepEqual(localizeDescribe(plain, 'roman'), plain);
});

test('get_text in a script also writes structured variants in that script, keeping sigla as legend keys', async () => {
  const canon = await import('../src/canon.mjs');
  const { textSegments } = await import('../src/variants.mjs');
  const { localizeText } = await import('../src/script.mjs');
  const { unit } = canon.resolve('MN 10');
  const { segments } = textSegments(unit, { variants: 'structured' });
  const out = localizeText({ title: unit.title, segments }, 'sinh', { text: 'MN 10', script: 'roman' });
  const v = out.segments.flatMap((s) => s.variants || []);
  assert.ok(v.length);
  for (const x of v) {
    assert.doesNotMatch(x.raw, /[āīūṃṅñṭḍṇḷ]/);
    for (const r of x.readings) { assert.doesNotMatch(r.reading, /[a-zāīū]/); for (const e of r.editions) assert.match(e.siglum, /[a-z]/); }
  }
});
